var n=`1321-empanada-de-pino`;var o=`world-1321`;var t=`CL`;var a=`south-america`;var r=8;var s=95;var g={en:`Empanada de Pino`,ua:`Емпанада де піно`};var l={en:`Empanada de Pino is a dish from Chile featuring all-purpose flour, ground beef, yellow onion, raisin. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Емпанада де піно, страва кухні країни Чилі з такими основними складниками: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, родзинки. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 17 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 17 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:17,i:[[`all-purpose-flour`,490,`g`],[`lard`,100,`g`],[`water`,235,`ml`],[`table-salt`,8,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:17,i:[[`ground-beef`,570,`g`],[`yellow-onion`,260,`g`],[`ground-cumin`,5,`g`],[`sweet-paprika`,7,`g`],[`raisin`,70,`g`]]},{en:`Boil the eggs for about 11 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 11 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:11,i:[[`chicken-egg`,3,`pcs`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[[`black-olives`,95,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 35 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 35 хвилин до готовності.`,t:[`baking`],m:35,i:[]}];var u={slug:n,id:o,country:`CL`,region:a,servings:8,minutes:95,title:g,text:l,steps:d};export{t as country,u as default,o as id,s as minutes,a as region,r as servings,n as slug,d as steps,l as text,g as title};